function(container, apiUrl, tables) {
  const logTableIndex = 12; // データ収集ログテーブルのインデックス
  const storeTableIndex = 1; // 店舗マスタテーブルのインデックス

  let allLogs = [];
  let stores = [];
  let autoRefreshInterval = null;

  // 店舗マスタを取得
  async function loadStores() {
    const storeData = await window.aivicApi.list(storeTableIndex);
    if (storeData) {
      stores = storeData;
    }
  }

  // 店舗名を取得する関数
  function getStoreName(storeId) {
    const store = stores.find(s => s.店舗ID === storeId);
    return store ? store.店舗名 : '不明';
  }

  // ステータス表示用の関数
  function getStatusBadge(status) {
    const statusColors = {
      '成功': '#28a745',
      '失敗': '#dc3545',
      '警告': '#ffc107',
      '実行中': '#17a2b8'
    };
    const color = statusColors[status] || '#6c757d';
    return `<span style="padding: 4px 8px; border-radius: 4px; background: ${color}; color: white; font-size: 12px;">${status}</span>`;
  }

  // 日時フォーマット関数
  function formatDateTime(dateStr) {
    if (!dateStr) return '-';
    const date = new Date(dateStr);
    return date.toLocaleString('ja-JP');
  }

  // サマリー更新関数
  function updateSummary(logs) {
    const successCount = logs.filter(log => log.処理ステータス === '成功').length;
    const errorCount = logs.filter(log => log.処理ステータス === '失敗').length;
    const warningCount = logs.filter(log => log.処理ステータス === '警告').length;

    const lastUpdate = logs.length > 0 ? 
      Math.max(...logs.map(log => new Date(log.収集開始日時 || 0).getTime())) : 0;

    container.querySelector('#summary-success').textContent = successCount;
    container.querySelector('#summary-error').textContent = errorCount;
    container.querySelector('#summary-warning').textContent = warningCount;
    container.querySelector('#summary-last-update').textContent = 
      lastUpdate > 0 ? formatDateTime(new Date(lastUpdate)) : '-';

    // システム状況インジケーター更新
    const statusIndicator = container.querySelector('#status-indicator');
    const recentErrors = logs.filter(log => {
      const logTime = new Date(log.収集開始日時);
      const oneHourAgo = new Date(Date.now() - 60 * 60 * 1000);
      return log.処理ステータス === '失敗' && logTime > oneHourAgo;
    }).length;

    if (recentErrors > 0) {
      statusIndicator.innerHTML = `
        <div style="width: 12px; height: 12px; border-radius: 50%; background: #dc3545;"></div>
        <span style="color: var(--text);">エラー発生中 (${recentErrors}件)</span>
      `;
    } else {
      statusIndicator.innerHTML = `
        <div style="width: 12px; height: 12px; border-radius: 50%; background: #28a745;"></div>
        <span style="color: var(--text);">正常稼働中</span>
      `;
    }
  }

  // ログ一覧再描画関数
  function renderLogs(logs) {
    const tbody = container.querySelector('#log-table-body');

    tbody.innerHTML = logs.map(log => `
      <tr data-id="${log.ログID}">
        <td>${formatDateTime(log.収集開始日時)}</td>
        <td>${log.データソース || '-'}</td>
        <td>${log.データ種別 || '-'}</td>
        <td>${getStoreName(log.店舗ID)}</td>
        <td>${getStatusBadge(log.処理ステータス)}</td>
        <td>${log.収集件数 || 0}</td>
        <td>${log.エラー件数 || 0}</td>
        <td>${log.処理時間秒 ? log.処理時間秒 + '秒' : '-'}</td>
        <td>${log.データ品質スコア || '-'}</td>
        <td>
          <button class="action-btn secondary detail-btn" data-id="${log.ログID}">詳細</button>
          ${log.処理ステータス === '失敗' ? 
            `<button class="action-btn secondary retry-btn" data-id="${log.ログID}">再実行</button>` : ''}
        </td>
      </tr>
    `).join('');

    container.querySelector('#log-count').textContent = `${logs.length}件`;
    updateSummary(logs);
  }

  // フィルタリング関数
  function applyFilters() {
    const dataSource = container.querySelector('#filter-data-source').value;
    const logLevel = container.querySelector('#filter-log-level').value;
    const startDate = container.querySelector('#filter-start-date').value;
    const endDate = container.querySelector('#filter-end-date').value;

    // 日付範囲の妥当性チェック
    if (startDate && endDate && new Date(startDate) > new Date(endDate)) {
      alert('開始日は終了日より前の日付を設定してください');
      return;
    }

    let filteredLogs = allLogs.filter(log => {
      // データソースフィルター
      if (dataSource && log.データソース !== dataSource) return false;

      // ログレベルフィルター
      if (logLevel && log.処理ステータス !== logLevel) return false;

      // 日付範囲フィルター
      if (startDate) {
        const logDate = new Date(log.収集開始日時);
        if (logDate < new Date(startDate)) return false;
      }
      if (endDate) {
        const logDate = new Date(log.収集開始日時);
        if (logDate > new Date(endDate)) return false;
      }

      return true;
    });

    renderLogs(filteredLogs);
  }

  // ログ詳細表示関数
  function showLogDetail(logId) {
    const log = allLogs.find(l => l.ログID === logId);
    if (!log) return;

    const content = container.querySelector('#log-detail-content');
    content.innerHTML = `
      <div style="display: grid; gap: 15px;">
        <div style="display: grid; grid-template-columns: 1fr 1fr; gap: 15px;">
          <div>
            <label style="font-weight: bold; color: var(--text);">ログID</label>
            <div style="color: var(--text-muted);">${log.ログID}</div>
          </div>
          <div>
            <label style="font-weight: bold; color: var(--text);">データ種別</label>
            <div style="color: var(--text-muted);">${log.データ種別 || '-'}</div>
          </div>
          <div>
            <label style="font-weight: bold; color: var(--text);">データソース</label>
            <div style="color: var(--text-muted);">${log.データソース || '-'}</div>
          </div>
          <div>
            <label style="font-weight: bold; color: var(--text);">店舗</label>
            <div style="color: var(--text-muted);">${getStoreName(log.店舗ID)}</div>
          </div>
          <div>
            <label style="font-weight: bold; color: var(--text);">収集開始日時</label>
            <div style="color: var(--text-muted);">${formatDateTime(log.収集開始日時)}</div>
          </div>
          <div>
            <label style="font-weight: bold; color: var(--text);">収集終了日時</label>
            <div style="color: var(--text-muted);">${formatDateTime(log.収集終了日時)}</div>
          </div>
          <div>
            <label style="font-weight: bold; color: var(--text);">処理ステータス</label>
            <div>${getStatusBadge(log.処理ステータス)}</div>
          </div>
          <div>
            <label style="font-weight: bold; color: var(--text);">処理時間</label>
            <div style="color: var(--text-muted);">${log.処理時間秒 ? log.処理時間秒 + '秒' : '-'}</div>
          </div>
          <div>
            <label style="font-weight: bold; color: var(--text);">収集件数</label>
            <div style="color: var(--text-muted);">${log.収集件数 || 0}</div>
          </div>
          <div>
            <label style="font-weight: bold; color: var(--text);">エラー件数</label>
            <div style="color: var(--text-muted);">${log.エラー件数 || 0}</div>
          </div>
          <div>
            <label style="font-weight: bold; color: var(--text);">データ品質スコア</label>
            <div style="color: var(--text-muted);">${log.データ品質スコア || '-'}</div>
          </div>
          <div>
            <label style="font-weight: bold; color: var(--text);">対象期間</label>
            <div style="color: var(--text-muted);">${formatDateTime(log.対象期間開始日)} ～ ${formatDateTime(log.対象期間終了日)}</div>
          </div>
        </div>
        ${log.エラーメッセージ ? `
          <div>
            <label style="font-weight: bold; color: var(--text);">エラーメッセージ</label>
            <div style="background: var(--bg-main); padding: 10px; border-radius: 4px; border-left: 3px solid #dc3545; color: var(--text); white-space: pre-wrap; max-height: 200px; overflow-y: auto;">${log.エラーメッセージ}</div>
          </div>
        ` : ''}
        ${log.備考 ? `
          <div>
            <label style="font-weight: bold; color: var(--text);">備考</label>
            <div style="background: var(--bg-main); padding: 10px; border-radius: 4px; color: var(--text); white-space: pre-wrap;">${log.備考}</div>
          </div>
        ` : ''}
      </div>
    `;

    container.querySelector('#log-detail-modal').classList.remove('hidden');
  }

  // CSVエクスポート関数
  function exportCSV() {
    const dataSource = container.querySelector('#filter-data-source').value;
    const logLevel = container.querySelector('#filter-log-level').value;
    const startDate = container.querySelector('#filter-start-date').value;
    const endDate = container.querySelector('#filter-end-date').value;

    let exportLogs = allLogs;

    // フィルター適用
    if (dataSource || logLevel || startDate || endDate) {
      exportLogs = allLogs.filter(log => {
        if (dataSource && log.データソース !== dataSource) return false;
        if (logLevel && log.処理ステータス !== logLevel) return false;
        if (startDate && new Date(log.収集開始日時) < new Date(startDate)) return false;
        if (endDate && new Date(log.収集開始日時) > new Date(endDate)) return false;
        return true;
      });
    }

    const headers = ['ログID', '収集開始日時', '収集終了日時', 'データ種別', 'データソース', '店舗名', '処理ステータス', '収集件数', 'エラー件数', '処理時間秒', 'データ品質スコア', 'エラーメッセージ', '備考'];

    const csvContent = '\uFEFF' + [
      headers.join(','),
      ...exportLogs.map(log => [
        log.ログID,
        log.収集開始日時,
        log.収集終了日時,
        log.データ種別,
        log.データソース,
        getStoreName(log.店舗ID),
        log.処理ステータス,
        log.収集件数 || 0,
        log.エラー件数 || 0,
        log.処理時間秒 || '',
        log.データ品質スコア || '',
        `"${(log.エラーメッセージ || '').replace(/"/g, '""')}"`,
        `"${(log.備考 || '').replace(/"/g, '""')}"`
      ].join(','))
    ].join('\n');

    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = `data_collection_logs_${new Date().toISOString().split('T')[0]}.csv`;
    link.click();
  }

  // エラーログ再実行関数
  async function retryLog(logId) {
    if (!confirm('このログの処理を再実行しますか？')) return;

    try {
      // 再実行フラグを更新
      const updated = await window.aivicApi.update(logTableIndex, logId, {
        再実行フラグ: true,
        処理ステータス: '実行中',
        更新日時: new Date().toISOString()
      });

      if (updated) {
        alert('再実行を開始しました');
        loadLogs();
      } else {
        alert('エラーログの再実行が失敗しました');
      }
    } catch (error) {
      alert('エラーログの再実行が失敗しました');
    }
  }

  // 自動更新機能
  function toggleAutoRefresh() {
    const toggle = container.querySelector('#auto-refresh-toggle');

    if (toggle.checked) {
      autoRefreshInterval = setInterval(() => {
        loadLogs();
      }, 30000); // 30秒間隔
    } else {
      if (autoRefreshInterval) {
        clearInterval(autoRefreshInterval);
        autoRefreshInterval = null;
      }
    }
  }

  // ログデータ読み込み関数
  async function loadLogs() {
    const logs = await window.aivicApi.list(logTableIndex);
    if (logs) {
      allLogs = logs.sort((a, b) => new Date(b.収集開始日時) - new Date(a.収集開始日時));
      renderLogs(allLogs);
    }
  }

  // 初期データ読み込み
  loadStores().then(() => {
    allLogs = (tables[logTableIndex]?.records || []).sort((a, b) => new Date(b.収集開始日時) - new Date(a.収集開始日時));
    renderLogs(allLogs);
    loadLogs();
  });

  // イベントリスナー設定

  // 検索・絞り込みボタン
  container.querySelector('#btn-search').addEventListener('click', applyFilters);

  // 条件クリアボタン
  container.querySelector('#btn-clear-filters').addEventListener('click', () => {
    container.querySelector('#filter-data-source').value = '';
    container.querySelector('#filter-log-level').value = '';
    container.querySelector('#filter-start-date').value = '';
    container.querySelector('#filter-end-date').value = '';
    renderLogs(allLogs);
  });

  // CSVエクスポートボタン
  container.querySelector('#btn-export-csv').addEventListener('click', exportCSV);

  // 自動更新トグル
  container.querySelector('#auto-refresh-toggle').addEventListener('change', toggleAutoRefresh);

  // アラート設定ボタン
  container.querySelector('#btn-alert-settings').addEventListener('click', () => {
    container.querySelector('#alert-settings-modal').classList.remove('hidden');
  });

  // モーダル閉じるボタン
  container.querySelector('#btn-close-modal').addEventListener('click', () => {
    container.querySelector('#log-detail-modal').classList.add('hidden');
  });

  container.querySelector('#btn-close-alert-modal').addEventListener('click', () => {
    container.querySelector('#alert-settings-modal').classList.add('hidden');
  });

  // アラート設定保存
  container.querySelector('#btn-save-alert-settings').addEventListener('click', () => {
    alert('アラート通知設定を保存しました');
    container.querySelector('#alert-settings-modal').classList.add('hidden');
  });

  // 行レベル操作のイベントデリゲーション
  container.addEventListener('click', async (e) => {
    // 詳細ボタン
    const detailBtn = e.target.closest('.detail-btn');
    if (detailBtn) {
      showLogDetail(detailBtn.dataset.id);
      return;
    }

    // 再実行ボタン
    const retryBtn = e.target.closest('.retry-btn');
    if (retryBtn) {
      await retryLog(retryBtn.dataset.id);
      return;
    }
  });

  // モーダル背景クリックで閉じる
  container.querySelector('#log-detail-modal').addEventListener('click', (e) => {
    if (e.target.id === 'log-detail-modal') {
      container.querySelector('#log-detail-modal').classList.add('hidden');
    }
  });

  container.querySelector('#alert-settings-modal').addEventListener('click', (e) => {
    if (e.target.id === 'alert-settings-modal') {
      container.querySelector('#alert-settings-modal').classList.add('hidden');
    }
  });
}
